const rows = items.map(i => i.json).filter(r => r.Email);
const count = (fn) => rows.filter(fn).length;
const by = (key) => rows.reduce((acc, r) => { const k = String(r[key] || 'unknown').trim() || 'unknown'; acc[k] = (acc[k] || 0) + 1; return acc; }, {});
const statuses = by('Status');
const grades = by('Lead Grade');
const sent = Object.entries(statuses).filter(([k]) => k.startsWith('Sent')).reduce((a, [, v]) => a + v, 0) + (statuses['Replied'] || 0);
const replied = statuses['Replied'] || 0;
const scores = rows.map(r => Number(r['Lead Score'])).filter(n => !isNaN(n));
return [{ json: {
  date: new Date().toISOString().slice(0, 10),
  total: rows.length,
  avgScore: scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length * 10) / 10 : 0,
  grades, statuses, sent, replied,
  replyRate: sent ? Math.round(replied / sent * 1000) / 10 : 0,
  approved: statuses['Approved'] || 0,
  awaitingApproval: statuses['Draft'] || 0,
  bounced: statuses['Bounced'] || 0
} }];

